// Reproduces CPython's repr() of a `bytes` object, as produced by print(bytes).
// Byte sequences are represented as Uint8Array throughout the project.

/**
 * Format a byte sequence exactly like Python's repr() of a bytes object.
 * Quote selection: single quotes by default; double quotes when the data
 * contains a single quote but no double quote.
 *
 * @param {Uint8Array|number[]} data
 * @returns {string} e.g. b'\xa1\xca'
 */
export function bytesRepr(data) {
  let hasSingle = false;
  let hasDouble = false;
  for (const b of data) {
    if (b === 0x27) hasSingle = true;
    else if (b === 0x22) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? '"' : "'";
  const quoteCode = quote.charCodeAt(0);

  let out = 'b' + quote;
  for (const b of data) {
    if (b === 0x5c || b === quoteCode) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b < 0x20 || b >= 0x7f) {
      out += '\\x' + b.toString(16).padStart(2, '0');
    } else {
      out += String.fromCharCode(b);
    }
  }
  return out + quote;
}

