// Minimal reimplementation of the construct library primitives used here,
// derived purely from their observable build() behavior (black-box).

/**
 * Error mirroring construct.core.IntegerError semantics.
 */
export class IntegerError extends Error {
  constructor(message) {
    super(message);
    this.name = 'IntegerError';
  }
}

/**
 * Error mirroring construct.core.BytesError semantics.
 */
export class BytesError extends Error {
  constructor(message) {
    super(message);
    this.name = 'BytesError';
  }
}

function buildInt(value, size, name) {
  const max = 2 ** (size * 8) - 1;
  if (!Number.isInteger(value) || value < 0 || value > max) {
    throw new IntegerError(
      `${name} cannot build from ${value}: not in range 0..${max}`,
    );
  }
  const out = new Uint8Array(size);
  for (let i = 0; i < size; i++) {
    out[i] = (value >> (i * 8)) & 0xff; // little-endian
  }
  return out;
}

/** construct.Int8ul.build: unsigned 8-bit integer -> 1 byte. */
export function int8ulBuild(value) {
  return buildInt(value, 1, 'Int8ul');
}

/** construct.Int16ul.build: unsigned 16-bit integer -> 2 bytes, little-endian. */
export function int16ulBuild(value) {
  return buildInt(value, 2, 'Int16ul');
}

/** construct.Bytes(n).build: fixed-length raw bytes, length must match exactly. */
export function bytesBuild(length, data) {
  if (data.length !== length) {
    throw new BytesError(
      `Bytes expected ${length} bytes, got ${data.length}`,
    );
  }
  return Uint8Array.from(data);
}

