// Minimal argparse-compatible parser (no external dependencies), matching the
// observable behavior of the Python argparse configuration used in test19.py:
// long options only, "--name value" and "--name=value" forms, required fields,
// int/str types, exit code 2 with usage on error.

import { basename } from 'node:path';

/**
 * @typedef {{ name: string, type: 'int'|'str', required: boolean }} ArgSpec
 */

/**
 * Parse argv in the style of Python's argparse.
 *
 * @param {string[]} argv   process.argv.slice(2)
 * @param {ArgSpec[]} specs argument specifications in declaration order
 * @param {string} progName program name for usage messages
 * @returns {Object<string, number|string>} parsed values keyed by option name
 */
export function parseArgs(argv, specs, progName = basename(process.argv[1] ?? 'test19')) {
  const usage = buildUsage(progName, specs);
  const fail = (message) => {
    process.stderr.write(usage + '\n');
    process.stderr.write(`${progName}: error: ${message}\n`);
    process.exit(2);
  };

  const byName = new Map(specs.map((s) => [s.name, s]));
  const values = {};

  for (let i = 0; i < argv.length; i++) {
    let token = argv[i];
    if (token === '-h' || token === '--help') {
      process.stdout.write(usage + '\n');
      process.exit(0);
    }
    if (!token.startsWith('--')) {
      fail(`unrecognized arguments: ${token}`);
    }
    token = token.slice(2);
    let inlineValue = null;
    const eq = token.indexOf('=');
    if (eq !== -1) {
      inlineValue = token.slice(eq + 1);
      token = token.slice(0, eq);
    }
    const spec = byName.get(token);
    if (!spec) {
      fail(`unrecognized arguments: --${token}`);
    }
    let raw;
    if (inlineValue !== null) {
      raw = inlineValue;
    } else {
      if (i + 1 >= argv.length) {
        fail(`argument --${token}: expected one argument`);
      }
      raw = argv[++i];
    }
    if (spec.type === 'int') {
      values[token] = parsePythonInt(raw, () =>
        fail(`argument --${token}: invalid int value: '${raw}'`),
      );
    } else {
      values[token] = raw;
    }
  }

  const missing = specs.filter((s) => s.required && !(s.name in values));
  if (missing.length > 0) {
    fail(
      'the following arguments are required: ' +
        missing.map((s) => '--' + s.name).join(', '),
    );
  }
  return values;
}

function buildUsage(progName, specs) {
  const parts = ['-h', ...specs.map((s) => `--${s.name} ${s.name.toUpperCase()}`)];
  let line = `usage: ${progName}`;
  for (const part of parts) {
    const candidate = `[${part}]`;
    if (line.length + 1 + candidate.length > 78) {
      line += '\n' + ' '.repeat(`usage: ${progName} `.length) + candidate;
    } else {
      line += ' ' + candidate;
    }
  }
  // argparse renders optionals without brackets when required; keep it simple:
  return line.replace(/\[--/g, '--').replace(/\](?=( |\n|$))/g, '');
}

/** Match Python int(str): optional surrounding whitespace, sign, decimal digits. */
function parsePythonInt(raw, fail) {
  const trimmed = raw.trim();
  if (!/^[+-]?\d+$/.test(trimmed)) {
    fail();
  }
  return parseInt(trimmed, 10);
}

