#!/usr/bin/env node
// Node.js ESM port of test19.py (construct-based byte building).
import { parseArgs } from './lib/argparse.mjs';
import { int8ulBuild, int16ulBuild, bytesBuild } from './lib/construct.mjs';
import { bytesRepr } from './lib/pybytes.mjs';

function main() {
  const args = parseArgs(process.argv.slice(2), [
    { name: 'a', type: 'int', required: true },
    { name: 'b', type: 'int', required: true },
    { name: 'c', type: 'int', required: true },
    { name: 'd', type: 'str', required: true },
    { name: 'e', type: 'int', required: true },
    { name: 'f', type: 'int', required: true },
    { name: 'g', type: 'int', required: true },
    { name: 'h', type: 'str', required: true },
    { name: 'i', type: 'int', required: true },
  ]);

  const encoder = new TextEncoder(); // UTF-8, like Python's str.encode()

  const results = [
    int8ulBuild(args.a), // first field
    int16ulBuild(args.b), // second field
    int8ulBuild(args.c), // third field
    bytesBuild(args.d.length, encoder.encode(args.d)), // string data, actual length
    int8ulBuild(args.f), // fifth field
    int8ulBuild(args.g), // sixth field
    int8ulBuild(args.i), // seventh field
    bytesBuild(args.h.length, encoder.encode(args.h)), // second string data
    // checksum field, kept in byte range (Python modulo semantics)
    int8ulBuild(((args.a + args.b + args.c) % 256 + 256) % 256),
  ];

  for (const result of results) {
    console.log(bytesRepr(result));
  }
}

main();

